def is_triangle_free(n, edges):
    adj = [set() for _ in range(n)]
    for u, v in edges:
        adj[u].add(v)
        adj[v].add(u)
    for i in range(n):
        for j in adj[i]:
            for k in adj[j]:
                if k in adj[i]:
                    return False
    return True

def is_maximal(n, edges):
    # A triangle-free graph is maximal if adding any non-edge creates a triangle.
    # This is equivalent to saying that for every pair of non-adjacent vertices (u, v),
    # there exists a vertex w such that (u, w) and (v, w) are edges.
    adj = [set() for _ in range(n)]
    for u, v in edges:
        adj[u].add(v)
        adj[v].add(u)

    for i in range(n):
        for j in range(i + 1, n):
            if j not in adj[i]:
                # Check if adding (i, j) creates a triangle
                # It creates a triangle if there exists w such that (i, w) and (j, w) are edges
                found_w = False
                for w in range(n):
                    if w in adj[i] and w in adj[j]:
                        found_w = True
                        break
                if not found_w:
                    return False, (i, j)
    return True, None

